// Every composition the film engine can render:
//   - FleetTest / FleetTestLong: the plan-1 engine and speed tests
//   - Job_<slug>: one per video job (film/src/jobs/index.ts, generated by `python -m tc filmjob build`),
//     playing its timed plan with its own fresh scenes (rule r17)
import React from 'react';
import { Composition } from 'remotion';
import { FleetTest } from './compositions/FleetTest';
import { JobFilm } from './film/JobFilm';
import { JOBS } from './jobs';

export const Root: React.FC = () => (
  <>
    {/* 8-second motion test (matches spike/art_dir/fleet_motion.mp4) */}
    <Composition id="FleetTest" component={FleetTest} width={1920} height={1080} fps={24} durationInFrames={192} />
    {/* 15-minute speed test: the same scene for 21,600 frames */}
    <Composition id="FleetTestLong" component={FleetTest} width={1920} height={1080} fps={24} durationInFrames={21600} />
    {JOBS.map((j) => (
      <Composition key={j.slug} id={`Job-${j.slug.replace(/_/g, '-')}`} component={JobFilm as any} width={1920} height={1080}
        fps={j.plan.fps} durationInFrames={Math.max(1, j.plan.frames)} defaultProps={{ slug: j.slug }} />
    ))}
  </>
);
